"use strict";(self.webpackChunksedelpeuch_net=self.webpackChunksedelpeuch_net||[]).push([["14285"],{14817(e,n,t){t.r(n),t.d(n,{metadata:()=>i,default:()=>d,frontMatter:()=>s,contentTitle:()=>a,toc:()=>u,assets:()=>l});var i=JSON.parse('{"id":"projects/professionnel/crob","title":"C-Rob - Plateforme robotique modulaire sous ROS 2","description":"C-Rob, d\xe9monstrateur RoboCup@Home du CATIE con\xe7u en interne : base mobile holonome sous Zephyr et micro-ROS, PC embarqu\xe9 ROS 2 Jazzy conteneuris\xe9, navigation Nav2, perception IA \xe0 la demande et jumeau num\xe9rique Gazebo. Coordination technique et lead ROS 2 Python.","source":"@site/docs/projects/professionnel/crob.md","sourceDirName":"projects/professionnel","slug":"/projects/professionnel/crob","permalink":"/docs/projects/professionnel/crob","draft":false,"unlisted":false,"tags":[{"inline":true,"label":"robotique","permalink":"/docs/tags/robotique"},{"inline":true,"label":"ros2","permalink":"/docs/tags/ros-2"},{"inline":true,"label":"zephyr","permalink":"/docs/tags/zephyr"},{"inline":true,"label":"micro-ros","permalink":"/docs/tags/micro-ros"},{"inline":true,"label":"nav2","permalink":"/docs/tags/nav-2"},{"inline":true,"label":"gazebo","permalink":"/docs/tags/gazebo"},{"inline":true,"label":"docker","permalink":"/docs/tags/docker"},{"inline":true,"label":"architecture","permalink":"/docs/tags/architecture"}],"version":"current","lastUpdatedAt":1795348395000,"frontMatter":{"title":"C-Rob - Plateforme robotique modulaire sous ROS 2","description":"C-Rob, d\xe9monstrateur RoboCup@Home du CATIE con\xe7u en interne : base mobile holonome sous Zephyr et micro-ROS, PC embarqu\xe9 ROS 2 Jazzy conteneuris\xe9, navigation Nav2, perception IA \xe0 la demande et jumeau num\xe9rique Gazebo. Coordination technique et lead ROS 2 Python.","tags":["robotique","ros2","zephyr","micro-ros","nav2","gazebo","docker","architecture"]},"sidebar":"tutorialSidebar","previous":{"title":"CI/CD - Workflows GitHub Actions mutualis\xe9s","permalink":"/docs/projects/professionnel/cicd"},"next":{"title":"GitHub ARC - Runners CI/CD auto-h\xe9berg\xe9s sur Kubernetes","permalink":"/docs/projects/professionnel/github-arc-kubeadm"}}'),r=t(74848),o=t(28453);let s={title:"C-Rob - Plateforme robotique modulaire sous ROS 2",description:"C-Rob, d\xe9monstrateur RoboCup@Home du CATIE con\xe7u en interne : base mobile holonome sous Zephyr et micro-ROS, PC embarqu\xe9 ROS 2 Jazzy conteneuris\xe9, navigation Nav2, perception IA \xe0 la demande et jumeau num\xe9rique Gazebo. Coordination technique et lead ROS 2 Python.",tags:["robotique","ros2","zephyr","micro-ros","nav2","gazebo","docker","architecture"]},a,l={},u=[{value:"Contexte",id:"contexte",level:2},{value:"Architecture",id:"architecture",level:2},{value:"R\xe9alisations",id:"r\xe9alisations",level:2},{value:"Sp\xe9cification",id:"sp\xe9cification",level:3},{value:"Organisation et d\xe9ploiement",id:"organisation-et-d\xe9ploiement",level:3},{value:"Description et simulation",id:"description-et-simulation",level:3},{value:"Pilotes mat\xe9riels",id:"pilotes-mat\xe9riels",level:3},{value:"Navigation",id:"navigation",level:3},{value:"Perception",id:"perception",level:3},{value:"Embarqu\xe9 et interface",id:"embarqu\xe9-et-interface",level:3},{value:"D\xe9cisions techniques",id:"d\xe9cisions-techniques",level:2},{value:"R\xf4le",id:"r\xf4le",level:2},{value:"R\xe9sultats",id:"r\xe9sultats",level:2},{value:"Limites connues",id:"limites-connues",level:2},{value:"Liens",id:"liens",level:2}];function c(e){let n={a:"a",h2:"h2",h3:"h3",li:"li",mermaid:"mermaid",p:"p",strong:"strong",ul:"ul",...(0,o.R)(),...e.components},{ProjectMeta:t}=n;return t||function(e,n){throw Error("Expected "+(n?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}("ProjectMeta",!0),(0,r.jsxs)(r.Fragment,{children:[(0,r.jsx)("img",{src:"/img/project/crob/crob.png",alt:"Le robot C-Rob : base mobile holonome et module central C2I avec \xe9cran et cam\xe9ras",style:{maxWidth:"320px",width:"100%",margin:"2rem auto",display:"block",borderRadius:"8px",border:"1px solid var(--ifm-color-emphasis-300)"}}),"\n",(0,r.jsx)(t,{start:"2024",role:"Coordination technique, lead ROS 2 (Python)",domain:"Robotique de service modulaire, architecture distribu\xe9e, navigation, perception",stack:["ROS 2","Python","Zephyr","micro-ROS","Nav2","Gazebo","Docker","GitHub Actions"]}),"\n",(0,r.jsx)(n.h2,{id:"contexte",children:"Contexte"}),"\n",(0,r.jsxs)(n.p,{children:["Pendant six ans, l'\xe9quipe CATIE Robotics a concouru \xe0 la RoboCup@Home avec un TIAGo de PAL Robotics (voir ",(0,r.jsx)(n.a,{href:"/docs/projects/professionnel/robocup-home-2023-catie",children:"RoboCup@Home 2023"}),"). Une plateforme commerciale ferm\xe9e impose ses limites : capteurs et calculateur fig\xe9s, firmware inaccessible, pi\xe8ces et \xe9volutions d\xe9pendantes du constructeur. D\xe9but 2024, le CATIE a lanc\xe9 un groupe de travail pour concevoir sa propre plateforme : C-Rob, un d\xe9monstrateur de robotique de service dont toute la cha\xeene (m\xe9canique, \xe9lectronique, firmware, logiciel) est ma\xeetris\xe9e en interne."]}),"\n",(0,r.jsx)(n.p,{children:"Le cahier des charges est issu de l'analyse des \xe9preuves RoboCup@Home et des besoins du CATIE : navigation rapide et pr\xe9cise en int\xe9rieur (passage de portes de 70 cm, \xe9vitement d'obstacles dynamiques, suivi de personnes), perception de l'environnement \xe0 360\xb0, d\xe9tection et r\xe9-identification de personnes, et \xe0 terme manipulation d'objets. La plateforme est pens\xe9e comme un empilement de modules d\xe9tachables :"}),"\n",(0,r.jsxs)(n.ul,{children:["\n",(0,r.jsxs)(n.li,{children:[(0,r.jsx)(n.strong,{children:"Base mobile"})," : trois roues omnidirectionnelles (cin\xe9matique holonome), trois LiDAR 2D en couronne, batteries et carte d'alimentation, calculateur temps r\xe9el sous Zephyr."]}),"\n",(0,r.jsxs)(n.li,{children:[(0,r.jsx)(n.strong,{children:"Module central C2I"})," : PC embarqu\xe9 sous ROS 2 Jazzy, cam\xe9ras RGB-D OAK-D, \xe9cran, haut-parleur et bandeaux LED pour l'interaction."]}),"\n",(0,r.jsxs)(n.li,{children:[(0,r.jsx)(n.strong,{children:"Module bras"})," : pr\xe9vu dans la sp\xe9cification, pas encore int\xe9gr\xe9."]}),"\n"]}),"\n",(0,r.jsx)(n.h2,{id:"architecture",children:"Architecture"}),"\n",(0,r.jsx)(n.p,{children:"Le logiciel se r\xe9partit sur deux niveaux. Les microcontr\xf4leurs de la base mobile, sous Zephyr, g\xe8rent tout ce qui rel\xe8ve du temps r\xe9el et de la s\xfbret\xe9 : commande des moteurs, odom\xe9trie, alimentation, arr\xeat d'urgence. Ils dialoguent entre eux sur un bus CAN. Le calculateur temps r\xe9el de la base se pr\xe9sente au reste du robot comme un n\u0153ud ROS 2 ordinaire, gr\xe2ce \xe0 micro-ROS, par le r\xe9seau Ethernet interne. Le PC embarqu\xe9 ex\xe9cute ROS 2 : chaque bloc fonctionnel (pilotes mat\xe9riels, description du robot, navigation, perception, interface web) est un paquet distinct, livr\xe9 dans sa propre image Docker."}),"\n",(0,r.jsx)(n.mermaid,{value:'flowchart TD\n  subgraph base["Base mobile, Zephyr"]\n    psu["Carte d\'alimentation"] --\x3e|CAN| ecu["Calculateur<br/>temps r\xe9el"]\n    mot["3 contr\xf4leurs<br/>moteur"] <--\x3e|CAN| ecu\n  end\n  subgraph pc["PC embarqu\xe9, ROS 2"]\n    pilotes["Pilotes mat\xe9riels"]\n    nav["Navigation"]\n    perc["Perception"]\n    web["Interface web"]\n  end\n  ecu --\x3e|"micro-ROS,<br/>Ethernet"| pilotes\n  capteurs["3 LiDAR,<br/>2 cam\xe9ras"] --\x3e pilotes\n  pilotes --\x3e nav\n  pilotes --\x3e perc\n  nav --\x3e web\n  perc --\x3e web\n  sim["Jumeau num\xe9rique<br/>Gazebo"] -.->|"remplace<br/>le mat\xe9riel"| nav'}),"\n",(0,r.jsx)(n.h2,{id:"r\xe9alisations",children:"R\xe9alisations"}),"\n",(0,r.jsx)(n.h3,{id:"sp\xe9cification",children:"Sp\xe9cification"}),"\n",(0,r.jsx)(n.p,{children:"La phase de sp\xe9cification de 2024 a produit l'analyse des besoins par axe (navigation, perception, IA, manipulation) : pour chaque axe, ce qu'exige la RoboCup@Home, ce qui int\xe9resse le CATIE au-del\xe0 de la comp\xe9tition, et les d\xe9pendances avec les autres axes. Les \xe9tats de l'art (roues holonomes, bras collaboratifs, capteurs) ont \xe9t\xe9 men\xe9s en \xe9quipe. Les sch\xe9mas d'architecture du robot (topologie r\xe9seau, liaisons des capteurs, d\xe9coupage en modules d\xe9tachables) ont \xe9t\xe9 compl\xe9t\xe9s par l'\xe9quipe \xe9lectronique pour le budget d'alimentation. Cette phase a fix\xe9 les choix structurants : cin\xe9matique holonome, LiDAR en couronne, calculateur temps r\xe9el distinct du PC embarqu\xe9."}),"\n",(0,r.jsx)(n.h3,{id:"organisation-et-d\xe9ploiement",children:"Organisation et d\xe9ploiement"}),"\n",(0,r.jsx)(n.p,{children:"Le logiciel est d\xe9coup\xe9 en un d\xe9p\xf4t par bloc fonctionnel (pilotes mat\xe9riels, description, navigation, perception, messages, interface web). Un d\xe9p\xf4t racine les assemble en un espace de travail ROS 2 et r\xe9f\xe9rence aussi les firmwares, ce qui fige une combinaison coh\xe9rente de versions. Cet espace de travail fournit une image de base ROS 2 en deux variantes, l'une pour l'environnement de d\xe9veloppement, l'autre pour le robot. Chaque paquet construit sa propre image \xe0 partir de cette base et la publie sur le registre de conteneurs de GitHub. Sur le robot, Docker Compose assemble les services ; chacun v\xe9rifie en continu que son n\u0153ud principal r\xe9pond et red\xe9marre seul en cas de panne."}),"\n",(0,r.jsx)(n.p,{children:"Toute la configuration du robot tient dans un seul fichier : nom du robot, simulation ou mat\xe9riel r\xe9el, carte, monde simul\xe9, param\xe8tres de navigation. Chaque conteneur le lit au d\xe9marrage et le valide contre un sch\xe9ma : une valeur absente ou mal form\xe9e arr\xeate le lancement, au lieu de produire un comportement incoh\xe9rent plus loin."}),"\n",(0,r.jsx)(n.p,{children:"Tous les d\xe9p\xf4ts partagent la m\xeame cha\xeene d'int\xe9gration continue : v\xe9rifications avant commit, compilation et tests ROS 2, analyse et publication de l'image Docker, nouvelle version publi\xe9e automatiquement quand le num\xe9ro du paquet change, mise \xe0 jour hebdomadaire des outils de v\xe9rification."}),"\n",(0,r.jsx)(n.h3,{id:"description-et-simulation",children:"Description et simulation"}),"\n",(0,r.jsx)(n.p,{children:"La description du robot est modulaire : base, module central, roues omnidirectionnelles mod\xe9lis\xe9es rouleau par rouleau, deux cam\xe9ras et trois LiDAR, chaque composant \xe9tant un bloc r\xe9utilisable plac\xe9 par sa position. Elle est g\xe9n\xe9r\xe9e au lancement pour le robot r\xe9el comme pour la simulation, avec des erreurs explicites quand un fichier est mal form\xe9."}),"\n",(0,r.jsx)(n.p,{children:"Le paquet de simulation lance Gazebo, y place le robot et relie les deux mondes : commandes de vitesse, odom\xe9trie, rep\xe8res, \xe9tats des articulations et mesures des LiDAR. Les mesures simul\xe9es sont republi\xe9es sous les m\xeames noms et dans les m\xeames rep\xe8res que celles du robot r\xe9el. La navigation se lance donc \xe0 l'identique en simulation et sur le robot ; seul le fichier de configuration change."}),"\n",(0,r.jsx)(n.h3,{id:"pilotes-mat\xe9riels",children:"Pilotes mat\xe9riels"}),"\n",(0,r.jsx)(n.p,{children:"Le paquet des pilotes regroupe tout ce qui parle au mat\xe9riel : liaison avec le calculateur de la base, pilote des LiDAR (acquisition et configuration \xe0 distance), pilote des cam\xe9ras, conversion de l'odom\xe9trie brute de la base en odom\xe9trie ROS 2 compl\xe8te, fusion des images des deux cam\xe9ras en nuage de points, et surveillance des cam\xe9ras avec relance automatique quand un flux se fige. Un lancement unique, pilot\xe9 par le fichier de configuration, d\xe9marre l'ensemble."}),"\n",(0,r.jsx)(n.p,{children:"Deux fonctions relient le logiciel au mat\xe9riel du robot. L'arr\xeat s\xe9curis\xe9 r\xe9pond \xe0 une demande de la carte d'alimentation : tous les n\u0153uds s'arr\xeatent proprement, puis le syst\xe8me s'\xe9teint si l'option est activ\xe9e. Les bandeaux LED se pilotent par un message ROS 2 d\xe9di\xe9 (effet, couleurs, luminosit\xe9, vitesse), que le contr\xf4leur LED traduit en commandes."}),"\n",(0,r.jsx)(n.h3,{id:"navigation",children:"Navigation"}),"\n",(0,r.jsx)(n.p,{children:"La navigation repose sur Nav2 : localisation sur une carte, planification de trajectoire, \xe9vitement d'obstacles, surveillance des collisions et navigation par points de passage. La cartographie 2D est faite avec Cartographer, \xe0 partir des trois LiDAR et de l'odom\xe9trie, et la t\xe9l\xe9op\xe9ration au clavier sert pendant les phases de cartographie. Le contr\xf4leur MPPI a \xe9t\xe9 retenu parce qu'il \xe9chantillonne directement des commandes en translation dans toutes les directions et en rotation : il exploite la cin\xe9matique holonome de la base, l\xe0 o\xf9 un contr\xf4leur pens\xe9 pour un robot \xe0 deux roues motrices la bride."}),"\n",(0,r.jsx)(n.h3,{id:"perception",children:"Perception"}),"\n",(0,r.jsx)(n.p,{children:"La perception a \xe9t\xe9 d\xe9velopp\xe9e en grande partie pendant un stage de fin d'\xe9tudes, sur des mod\xe8les fournis par le d\xe9partement IA du CATIE. Un n\u0153ud chef d'orchestre pilote des n\u0153uds sp\xe9cialis\xe9s (objets, personnes), qui lancent \xe0 leur tour les mod\xe8les : d\xe9tection et segmentation d'objets, estimation de la pose, et r\xe9-identification, qui garde une biblioth\xe8que de signatures des personnes d\xe9j\xe0 rencontr\xe9es. Chaque mod\xe8le tourne dans son propre processus, avec ses propres d\xe9pendances, et red\xe9marre seul s'il s'arr\xeate. Une demande de perception renvoie un retour de progression jusqu'\xe0 son r\xe9sultat. Les interfaces (demandes et messages) sont regroup\xe9es dans un paquet partag\xe9 par tous les blocs."}),"\n",(0,r.jsx)(n.h3,{id:"embarqu\xe9-et-interface",children:"Embarqu\xe9 et interface"}),"\n",(0,r.jsx)(n.p,{children:"Les firmwares sont le travail de l'\xe9quipe \xe9lectronique et embarqu\xe9. Le calculateur de la base, un microcontr\xf4leur STM32 sous Zephyr, calcule la cin\xe9matique holonome, pilote les trois contr\xf4leurs moteur, int\xe8gre l'odom\xe9trie et la publie par micro-ROS, avec l'\xe9tat des deux batteries remont\xe9 par la carte d'alimentation. La carte d'alimentation g\xe8re le choix de la batterie, l'arr\xeat d'urgence et la demande d'extinction. Un module commun d\xe9finit le protocole d'\xe9change entre ces cartes. C\xf4t\xe9 op\xe9rateur, une interface web, d\xe9velopp\xe9e elle aussi pendant le stage, affiche l'\xe9tat du robot (batteries, cam\xe9ras, personnes reconnues) et permet de le piloter au joystick."}),"\n",(0,r.jsx)(n.h2,{id:"d\xe9cisions-techniques",children:"D\xe9cisions techniques"}),"\n",(0,r.jsxs)(n.ul,{children:["\n",(0,r.jsxs)(n.li,{children:[(0,r.jsx)(n.strong,{children:"Temps r\xe9el sur microcontr\xf4leur, intelligence sur PC."})," La commande des moteurs, l'arr\xeat d'urgence et la gestion des batteries ne d\xe9pendent ni de Linux ni de l'\xe9tat de ROS 2. Un red\xe9marrage du PC embarqu\xe9 ou d'un conteneur ne laisse jamais la base sans contr\xf4le."]}),"\n",(0,r.jsxs)(n.li,{children:[(0,r.jsx)(n.strong,{children:"micro-ROS sur Ethernet, \xe0 la place d'une liaison s\xe9rie maison."})," La base appara\xeet comme un n\u0153ud ROS 2 parmi d'autres : ses donn\xe9es s'inspectent, s'enregistrent et se rejouent avec les outils standard. Le microcontr\xf4leur n'envoie qu'une odom\xe9trie minimale ; l'odom\xe9trie compl\xe8te et les rep\xe8res sont calcul\xe9s c\xf4t\xe9 PC, o\xf9 le calcul ne co\xfbte rien."]}),"\n",(0,r.jsxs)(n.li,{children:[(0,r.jsx)(n.strong,{children:"Un d\xe9p\xf4t et une image par bloc fonctionnel."})," Chaque bloc se versionne, se teste et se d\xe9ploie seul. Les \xe9quipes embarqu\xe9, navigation et perception avancent ainsi en parall\xe8le sans se bloquer."]}),"\n",(0,r.jsxs)(n.li,{children:[(0,r.jsx)(n.strong,{children:"Simulation et robot r\xe9el interchangeables."})," M\xeames noms de donn\xe9es, m\xeames rep\xe8res, m\xeames lancements : le jumeau num\xe9rique permet de d\xe9velopper et de tester la navigation sur n'importe quel poste, sans mobiliser le robot."]}),"\n",(0,r.jsxs)(n.li,{children:[(0,r.jsx)(n.strong,{children:"Perception \xe0 la demande."})," Avec un calcul embarqu\xe9 limit\xe9, les mod\xe8les ne tournent pas en permanence : chacun s'active quand la t\xe2che en cours en a besoin, dans un processus isol\xe9 dont la panne n'emporte pas le reste."]}),"\n"]}),"\n",(0,r.jsx)(n.h2,{id:"r\xf4le",children:"R\xf4le"}),"\n",(0,r.jsx)(n.p,{children:"Le projet est port\xe9 par le groupe de travail robotique du CATIE. Ma part couvre la coordination technique : animation de la phase de sp\xe9cification et sch\xe9mas d'architecture, d\xe9coupage du robot en modules et en d\xe9p\xf4ts, interfaces entre les \xe9quipes, conventions communes (int\xe9gration continue, v\xe9rifications, journal des versions, documentation de chaque paquet) et suivi de l'int\xe9gration. C\xf4t\xe9 d\xe9veloppement, j'ai con\xe7u l'espace de travail et le d\xe9ploiement Docker, la description et la simulation, les pilotes mat\xe9riels avec l'arr\xeat s\xe9curis\xe9 et le pilotage des LED, la mise en place de Nav2, ainsi que la structure de la perception et des messages. Un stagiaire a d\xe9velopp\xe9 la perception, l'interface web, la surveillance et la fusion des cam\xe9ras, la cartographie et le r\xe9glage de la navigation. Les firmwares viennent de l'\xe9quipe \xe9lectronique et embarqu\xe9, les mod\xe8les de perception du d\xe9partement IA."}),"\n",(0,r.jsx)(n.h2,{id:"r\xe9sultats",children:"R\xe9sultats"}),"\n",(0,r.jsx)(n.p,{children:"C-Rob est une plateforme ma\xeetris\xe9e de bout en bout, de la carte d'alimentation jusqu'\xe0 la perception, con\xe7ue et assembl\xe9e au CATIE. La base mobile holonome se pilote depuis ROS 2 et sait cartographier, se localiser et naviguer seule. Le jumeau num\xe9rique reproduit les interfaces du robot r\xe9el : il sert au d\xe9veloppement et \xe0 la prise en main par les nouveaux contributeurs. Toute la pile est conteneuris\xe9e et versionn\xe9e, si bien qu'une mise \xe0 jour du robot consiste \xe0 changer le fichier de configuration et \xe0 r\xe9cup\xe9rer les images publi\xe9es par l'int\xe9gration continue. La d\xe9tection d'objets, l'estimation de pose et la r\xe9-identification de personnes ont \xe9t\xe9 d\xe9montr\xe9es sur le robot."}),"\n",(0,r.jsx)(n.h2,{id:"limites-connues",children:"Limites connues"}),"\n",(0,r.jsxs)(n.ul,{children:["\n",(0,r.jsx)(n.li,{children:"Le module bras, sp\xe9cifi\xe9 d\xe8s 2024, n'est pas int\xe9gr\xe9."}),"\n",(0,r.jsx)(n.li,{children:"Docker Compose ne lance pas encore tous les blocs : la perception et la cartographie d\xe9marrent \xe0 part."}),"\n",(0,r.jsx)(n.li,{children:"La navigation ne voit que ce que voient les trois LiDAR : un obstacle hors de leur plan (plateau de table, objet pos\xe9 en hauteur) lui \xe9chappe tant que les cam\xe9ras ne sont pas branch\xe9es sur l'\xe9vitement d'obstacles."}),"\n",(0,r.jsx)(n.li,{children:"La reconnaissance vocale et les sc\xe9narios des \xe9preuves RoboCup@Home, qui existaient sur la plateforme pr\xe9c\xe9dente, ne sont pas encore port\xe9s sur C-Rob."}),"\n"]}),"\n",(0,r.jsx)(n.h2,{id:"liens",children:"Liens"}),"\n",(0,r.jsxs)(n.ul,{children:["\n",(0,r.jsx)(n.li,{children:(0,r.jsx)(n.a,{href:"https://www.catie.fr/wp-content/uploads/2026/04/RA2025_web.pdf",children:"Rapport d'activit\xe9s CATIE 2025 (PDF)"})}),"\n"]})]})}function d(e={}){let{wrapper:n}={...(0,o.R)(),...e.components};return n?(0,r.jsx)(n,{...e,children:(0,r.jsx)(c,{...e})}):c(e)}},28453(e,n,t){t.d(n,{R:()=>s,x:()=>a});var i=t(96540);let r={},o=i.createContext(r);function s(e){let n=i.useContext(o);return i.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function a(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(r):e.components||r:s(e.components),i.createElement(o.Provider,{value:n},e.children)}}}]);